# Generated by secure-by-design v0.1.0 for DPDP §8(6) (Breach Notification).
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/breach_notifier.md
#
# Scaffold for personal-data-breach reporting. DPDP §8(6) requires the data
# fiduciary to notify the Data Protection Board and affected data principals
# in the event of a personal data breach. The DPDP Rules, 2025 set the form,
# timeline and content and commence in phases; this scaffold does not map them.
# It is a shape, not the final transport.

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass, field
from datetime import datetime
from typing import Literal, Protocol

from ..security.audit_log import audit_log

BreachSeverity = Literal['low', 'medium', 'high', 'critical']


@dataclass(frozen=True)
class BreachReport:
    detected_at: datetime
    nature_of_breach: str                    # free text — what happened
    affected_categories: list[str]           # dataCategory names from manifest
    estimated_data_principals_affected: int
    is_ongoing: bool
    severity: BreachSeverity
    detected_by: str                         # employee ID, system ID, external report
    containment_actions_taken: list[str] = field(default_factory=list)
    root_cause_initial: str | None = None


@dataclass(frozen=True)
class PrincipalNotification:
    sent: int
    failed: int


class BreachNotifier(Protocol):
    async def notify_board(self, report: BreachReport) -> str:
        """
        Send the notification to the Data Protection Board. Returns a ticket ID.
        Replace with your actual transport for the form the Rules prescribe.
        """
        ...

    async def notify_data_principals(self, report: BreachReport, principal_ids: Sequence[str]) -> PrincipalNotification:
        """
        Notify affected data principals through the appropriate channel.
        Channel comes from manifest.breachNotification.dataSubjectNotifyChannel.
        """
        ...


_notifier: BreachNotifier | None = None


def set_breach_notifier(notifier: BreachNotifier) -> None:
    global _notifier
    _notifier = notifier


async def report_breach(report: BreachReport) -> str:
    """
    Report a personal data breach. Always log first. Notification proceeds
    asynchronously per your incident-response runbook. Returns the Board ticket ID.
    """
    await audit_log.event(
        'breach.detected',
        actor=report.detected_by,
        severity='CRITICAL' if report.severity == 'critical' else 'ERROR',
        attrs={
            'detected_at': report.detected_at.isoformat(),
            'categories': report.affected_categories,
            'estimated_affected': report.estimated_data_principals_affected,
            'is_ongoing': report.is_ongoing,
            'severity': report.severity,
        },
    )

    if _notifier is None:
        # Logged, but transport not configured. The on-call engineer must escalate manually.
        raise RuntimeError(
            'secure-by-design: BreachNotifier not configured. Breach is logged but '
            'NOT yet reported to the Data Protection Board. Escalate immediately per runbook.'
        )

    ticket_id = await _notifier.notify_board(report)
    await audit_log.event('breach.board-notified', actor='system:breach-notifier', attrs={'ticket_id': ticket_id})

    # Affected-principals notification is a separate async step in most products,
    # because identifying who-was-affected takes investigation. Trigger it once
    # your incident response has the affected-IDs list.
    return ticket_id


async def notify_affected_principals(report: BreachReport, affected_ids: Sequence[str]) -> PrincipalNotification:
    """Phase 2: once the affected-IDs list is known, dispatch principal notifications."""
    if _notifier is None:
        raise RuntimeError('secure-by-design: BreachNotifier not configured.')
    result = await _notifier.notify_data_principals(report, affected_ids)
    await audit_log.event(
        'breach.principals-notified',
        actor='system:breach-notifier',
        attrs={'sent': result.sent, 'failed': result.failed, 'attempted': len(affected_ids)},
    )
    return result
